window.ScripturaLexicons.BDAG_PART_0228 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-01\" data-source=\"BDAG\" data-search=\"μεγαλεῖος, α, ον adjetivo substantivado grandioso; grandeza; feitos grandiosos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγαλεῖος, α, ον</td><td>adjetivo substantivado</td><td>grandioso; grandeza; feitos grandiosos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-02\" data-source=\"BDAG\" data-search=\"μεγαλειότης, ητος, ἡ substantivo feminino grandeza; sublimidade; majestade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγαλειότης, ητος, ἡ</td><td>substantivo feminino</td><td>grandeza; sublimidade; majestade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-03\" data-source=\"BDAG\" data-search=\"μεγαλοπρέπεια, ας, ἡ substantivo feminino majestade; sublimidade de Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγαλοπρέπεια, ας, ἡ</td><td>substantivo feminino</td><td>majestade; sublimidade de Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-04\" data-source=\"BDAG\" data-search=\"μεγαλοπρεπής, ές adjetivo magnífico; sublime; majestoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγαλοπρεπής, ές</td><td>adjetivo</td><td>magnífico; sublime; majestoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-05\" data-source=\"BDAG\" data-search=\"μεγαλο(ρ)ρημονέω verbo empregar palavras grandiosas; vangloriar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγαλο(ρ)ρημονέω</td><td>verbo</td><td>empregar palavras grandiosas; vangloriar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-06\" data-source=\"BDAG\" data-search=\"μεγαλο(ρ)ρημοσύνη, ης, ἡ substantivo feminino fala orgulhosa; retórica arrogante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγαλο(ρ)ρημοσύνη, ης, ἡ</td><td>substantivo feminino</td><td>fala orgulhosa; retórica arrogante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-07\" data-source=\"BDAG\" data-search=\"μεγαλο(ρ)ρήμων, ονος adjetivo jactancioso; arrogante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγαλο(ρ)ρήμων, ονος</td><td>adjetivo</td><td>jactancioso; arrogante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-08\" data-source=\"BDAG\" data-search=\"μεγαλύνω verbo engrandecer; exaltar; glorificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγαλύνω</td><td>verbo</td><td>engrandecer; exaltar; glorificar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-09\" data-source=\"BDAG\" data-search=\"μεγάλως advérbio grandemente; muito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγάλως</td><td>advérbio</td><td>grandemente; muito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-10\" data-source=\"BDAG\" data-search=\"μεγαλωσύνη, ης, ἡ substantivo feminino majestade divina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγαλωσύνη, ης, ἡ</td><td>substantivo feminino</td><td>majestade divina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-11\" data-source=\"BDAG\" data-search=\"μέγας, μεγάλη, μέγα adjetivo grande; vasto; importante; extraordinário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέγας, μεγάλη, μέγα</td><td>adjetivo</td><td>grande; vasto; importante; extraordinário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-12\" data-source=\"BDAG\" data-search=\"μέγεθος, ους, τό substantivo neutro tamanho; grandeza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέγεθος, ους, τό</td><td>substantivo neutro</td><td>tamanho; grandeza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-13\" data-source=\"BDAG\" data-search=\"μεγιστάν, ᾶνος, ὁ substantivo masculino magnata; cortesão; grande personagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεγιστάν, ᾶνος, ὁ</td><td>substantivo masculino</td><td>magnata; cortesão; grande personagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-14\" data-source=\"BDAG\" data-search=\"μέγιστος remissão ver μέγας 4 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέγιστος</td><td>remissão</td><td>ver μέγας 4</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-15\" data-source=\"BDAG\" data-search=\"μεθερμηνεύω verbo traduzir; interpretar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεθερμηνεύω</td><td>verbo</td><td>traduzir; interpretar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-16\" data-source=\"BDAG\" data-search=\"μέθη, ης, ἡ substantivo feminino embriaguez; bebedeira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέθη, ης, ἡ</td><td>substantivo feminino</td><td>embriaguez; bebedeira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-17\" data-source=\"BDAG\" data-search=\"μεθιστάνω remissão ver μεθίστημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεθιστάνω</td><td>remissão</td><td>ver μεθίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-18\" data-source=\"BDAG\" data-search=\"μεθίστημι verbo transferir; remover; desencaminhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεθίστημι</td><td>verbo</td><td>transferir; remover; desencaminhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-19\" data-source=\"BDAG\" data-search=\"μεθοδεία, ας, ἡ substantivo feminino maquinação; astúcia; estratagema BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεθοδεία, ας, ἡ</td><td>substantivo feminino</td><td>maquinação; astúcia; estratagema</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0228-20\" data-source=\"BDAG\" data-search=\"μεθοδεύω verbo fraudar; enganar; perverter BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεθοδεύω</td><td>verbo</td><td>fraudar; enganar; perverter</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0228-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγαλεῖος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγαλεῖος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (ver verbete seguinte; X. e outros; inscrições, papiros, LXX; comparativo <span class=\"greek\">μεγαλειότερος</span> Just., A II, 10, 1), “magnífico, esplêndido, grandioso”; em nossa literatura, somente substantivado, acerca do que impressiona a mente ou o espírito: <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>., grandeza, sublimidade (Polyb. 3, 87, 5; 8, 1, 1; Artem. 3 p. 169, 1 <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σοφίας</span>; SIG 798, 4 [37 d.C.]; Sir 17:8; TestJob; TestLevi 11:6; Philo; Jos., Ant. 8, 49; 15, 187; Just., A II, 3, 3) <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπαγγελίας</span> 1 Cl 26:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">καλλονῆς</span> <span class=\"greek\">αὐτοῦ</span>, a beleza sublime dele (ou de Deus) 49:3.—Plural <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>., os feitos grandiosos (Dt 11:2; Ps 70:19; Sir 36:7; 42:21) <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:11</a>; cf. Hv 4, 2, 5; Hs 9, 18, 2. Em emprego absoluto v 4, 1, 8. Acerca dos grandes e bons feitos de Deus (TestJob 51:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:49</a>, variante textual (cf. Ps 70:19). <span class=\"greek\">πηλίκα</span> <span class=\"greek\">μεγαλεῖα</span> <span class=\"greek\">ἐδόθη</span> <span class=\"greek\">αὐτῷ</span>, que grandes feitos lhe foi concedido realizar (pela graça de Deus) AcPl Ha 6, 13. <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">δωρεῶν</span>, a grandeza das dádivas (de Deus) 1 Cl 32:1.—DELG s.v. <span class=\"greek\">μέγας</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγαλειότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγαλειότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (ver verbete precedente; Athen. 4, 6, 130s.; Vett. Val. 70, 4; OGI 666, 26 [século I d.C.], as pirâmides como visão imponente; 669, 9 [século I d.C.]; PGiss 40 I, 5; 11; LXX), em nossa literatura, somente em relação a uma figura divina ou a atributos divinos.</p><p class=\"entry-text\">① Qualidade ou condição de ocupar lugar superior em estima: grandeza, sublimidade, majestade (de Deus: Aristob. em Eus., PE 8, 10, 17; Jos., Ant. 1, 24; 8, 111, C. Ap. 2, 168); acerca de Ártemis <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:27</a>. Acerca de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:16</a>, cuja dignidade foi confirmada por uma voz celestial.</p><p class=\"entry-text\">② Qualidade ou condição de desfrutar de elevada estima em razão de realizações impressionantes: caráter impressionante, grandiosidade (cf. o emprego de <span class=\"greek\">θειότης</span>, ver esse verbete), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:43</a>, em referência a uma cura; Dg 10:5, acerca de ações que não corresponderiam ao caráter de Deus; IRo ins, acerca da manifestação da misericórdia divina. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">προνοίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δεσπότου</span>, a maravilhosa providência do Senhor 1 Cl 24:5.—DELG s.v. <span class=\"greek\">μέγας</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγαλοπρέπεια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγαλοπρέπεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (ver <span class=\"greek\">μέγας</span>, <span class=\"greek\">πρέπω</span> e o verbete seguinte; Hom. e outros; SIG 695, 14; papiros [como título honorífico]; LXX [somente nos Salmos, mas ali não é rara]), majestade, sublimidade, acerca de Deus, com a implicação de que a reverência imponente que Deus inspira procede de suas realizações impressionantes; com <span class=\"greek\">ἰσχύς</span> 1 Cl 60:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγαλοπρεπής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγαλοπρεπής</span>, <span class=\"greek\">ές</span> (ver verbete precedente; Hdt., Aristoph. e posteriores; inscrições, papiros, LXX; En 32:3; Philo; Jos., Ant. 9, 182; 13, 242), magnífico, sublime, majestoso, impressionante: <span class=\"greek\">δόξα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:17</a>; 1 Cl 9:2. <span class=\"greek\">κράτος</span> <span class=\"greek\">θεοῦ</span> 61:1. <span class=\"greek\">βούλησις</span> <span class=\"greek\">θεοῦ</span> 9:1. <span class=\"greek\">δωρεαὶ</span> <span class=\"greek\">θεοῦ</span> 19:2 (Diod S 3, 54, 6 <span class=\"greek\">δῶρα</span> <span class=\"greek\">μεγαλοπρεπῆ</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">θρησκεία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὑψίστου</span>, o culto elevado/imponente ao Altíssimo 45:7 (Appian, Bell. Civ. 5, 4 §15 <span class=\"greek\">τῇ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">μεγαλοπρεπῶς</span> <span class=\"greek\">ἔθυε</span>; cf. o adjetivo Theopomp. 115: Fgm. 344, Jac. p. 607, 16). <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">Χριστοῦ</span> 1 Cl 64 (cf. 2 Macc 8:15).—<span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">φιλοξενίας</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἦθος</span>, o caráter impressionante de vossa hospitalidade 1:2.—New Docs 2, 108s. DELG s.v. <span class=\"greek\">πρέπω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγαλο(ρ)ρημονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγαλο</span>(<span class=\"greek\">ρ</span>)<span class=\"greek\">ρημονέω</span> (ver <span class=\"greek\">μέγας</span>, <span class=\"greek\">ῥῆμα</span> e os dois verbetes seguintes), 1º aoristo <span class=\"greek\">ἐμεγαλορημόνησα</span> (Strabo 13, 1, 40; LXX; TestJob 41:1; ApcSed 14:12 p. 136, 22 Ja.), empregar palavras grandiosas, vangloriar-se 1 Cl 17:5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγαλο(ρ)ρημοσύνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγαλο</span>(<span class=\"greek\">ρ</span>)<span class=\"greek\">ρημοσύνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (ver o verbete precedente e o seguinte), fala orgulhosa, jactanciosa (Anonymus em Suda s.v. <span class=\"greek\">σεμνομυθοῦσιν</span>=Polyb. 38, 19, variante textual; Philostrat., Her. 2, 19 p. 161, 19; Alex. Ep. 15, 12 p. 205 M.=PSI 1285 IV, 33; 1 Km 2:3; Alex. Ep. 15, 12 p. 205; TestJob 42:1); no plural, retórica arrogante IEph 10:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγαλο(ρ)ρήμων, ονος</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγαλο</span>(<span class=\"greek\">ρ</span>)<span class=\"greek\">ρήμων</span>, <span class=\"greek\">ονος</span> (ver os dois verbetes precedentes; Philostrat., Vi. Apoll. 6, 11 p. 222, 21), jactancioso: <span class=\"greek\">γλῶσσα</span>, língua arrogante (Ps 11:4; 3 Macc 6:4; Jos., Ant. 20, 90, variante textual) 1 Cl 15:5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγαλύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγαλύνω</span> (ver <span class=\"greek\">μέγας</span>), imperfeito <span class=\"greek\">ἐμεγάλυνον</span>, médio <span class=\"greek\">ἐμεγαλυνόμην</span>; futuro <span class=\"greek\">μεγαλυνῶ</span>; 1º aoristo <span class=\"greek\">ἐμεγάλυνα</span> LXX. Passivo: futuro <span class=\"greek\">μεγαλυνθήσομαι</span>; 1º aoristo <span class=\"greek\">ἐμεγαλύνθην</span>; perfeito, 3ª pessoa do singular <span class=\"greek\">μεμεγάλυνται</span> Ezk 9:9 (“tornar grande/longo, engrandecer”, Aeschyl. e outros; Thu. 5, 98; POxy 1592, 3; LXX; TestLevi 18:3; JosAs 21:4 cód. A [p. 71, 21 Bat.]).</p><p class=\"entry-text\">① Fazer que algo seja grande, seja material ou imaterial: aumentar, alongar, engrandecer, <span class=\"greek\">τὶ</span>, alguma coisa: <span class=\"greek\">τὰ</span> <span class=\"greek\">κράσπεδα</span> (<span class=\"greek\">τῶν</span> <span class=\"greek\">ἱματίων</span>: acréscimo de variante textual, correto quanto ao assunto), as franjas (das vestes) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:5</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔλεος</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, demonstrar grande misericórdia a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:58</a> (cf. Gen 19:19 <span class=\"greek\">ἐμεγάλυνας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δικαιοσύνην</span> <span class=\"greek\">σου</span>). <span class=\"greek\">μ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομά</span> <span class=\"greek\">τινος</span>, engrandecer o nome de alguém 1 Cl 10:3 (Gen 12:2; também Eur., Bacch. 320); GJs 7:2; 12:1.—Passivo: aumentar, crescer (1 Km 2:21; 3 Km 10:26) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:15</a>. <span class=\"greek\">ἐμεγαλύνθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχή</span> <span class=\"greek\">μου</span>, meu espírito foi engrandecido, isto é, “estou tomado de admiração” GJs 5:2; 19:2 (cf. 1 Km 26:24).</p><p class=\"entry-text\">② Fazer que alguém seja tido em maior estima por meio de elogios ou feitos: exaltar, glorificar, engrandecer, falar elogiosamente de (Eur., Thu. e outros; LXX), com acusativo daquele que é louvado: <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span> (Sir 43:31) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:46</a> (UMittman-Richert, Magnifikat und Benediktus ’96). <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> (Ps 68:31.—Cf. Diod S 1, 20, 6 <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δύναμιν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:46</a>. Dos apóstolos: <span class=\"greek\">ἐμεγάλυνεν</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαός</span>, o povo falava deles com grande estima 5:13 (diferentemente NRSV). Os jactanciosos dizem: <span class=\"greek\">τ</span>. <span class=\"greek\">γλῶσσαν</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">μεγαλυνοῦμεν</span>, glorificaremos nossa língua, isto é, nossa fala demonstrará nossa superioridade 1 Cl 15:5 (Ps 11:5).—Passivo: ser glorificado, exaltado (2 Km 7:26): <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:17</a> (<span class=\"greek\">μ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομά</span> <span class=\"greek\">τινος</span> como em Gen 12:2; Eur., Bacch. 320 <span class=\"greek\">ὅταν</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">Πενθέως</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ὄνομα</span> <span class=\"greek\">μεγαλύνῃ</span> <span class=\"greek\">πόλις</span>). <span class=\"greek\">μεγαλυνθήσεται</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματί</span> <span class=\"greek\">μου</span>, Cristo será glorificado em minha pessoa (isto é, o prestígio de Cristo será promovido por intermédio de mim) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:20</a>. Com <span class=\"greek\">δοξασθῆναι</span> 1 Cl 32:3.—DELG s.v. <span class=\"greek\">μέγας</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγάλως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγάλως</span>, advérbio de <span class=\"greek\">μέγας</span> (Hom. e outros), grandemente: <span class=\"greek\">μ</span>. <span class=\"greek\">εἶναι</span> (com <span class=\"greek\">θαυμαστῶς</span>), ser grande Hv 3, 4, 1; Hs 5, 5, 4 (ver HLjungvik, Eranos 62, ’64, 28); sobre v 1, 3, 3, ver Dibelius, Hdb. Com <span class=\"greek\">εὐδόξως</span> 9, 18, 4. Empregado para intensificar um verbo: muito, grandemente (Polyb. 1, 52, 2; Herodian 4, 15, 2; Jos., Vi. 154; SibOr 5, 61): <span class=\"greek\">ἐβόησεν</span> <span class=\"greek\">μ</span>., soltou um rugido tremendo AcPl Ha 2, 6; <span class=\"greek\">ἐμαρτυρήθη</span> <span class=\"greek\">μ</span>. <span class=\"greek\">Ἀβραάμ</span>, Abraão recebeu um testemunho glorioso 1 Cl 17:2; <span class=\"greek\">χαρῆναι</span> <span class=\"greek\">μ</span>., alegrar-se muito (PAmh 39, 8 [século II a.C.] <span class=\"greek\">μεγάλως</span> <span class=\"greek\">ἐχάρημεν</span>; EpArist 42; 312) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:10</a>; Hs 8, 6. <span class=\"greek\">ἠγαλλιάσαντο</span> <span class=\"greek\">μ</span>. AcPl Ha 8, 5. <span class=\"greek\">συνεχάρην</span> … <span class=\"greek\">μ</span>. Pol. 1:1. <span class=\"greek\">παραδέχεσθαι</span> <span class=\"greek\">μ</span>., ser recebido calorosamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:4</a>, variante textual. <span class=\"greek\">δοξασθεὶς</span> <span class=\"greek\">μ</span>. 1 Cl 17:5; cf. <span class=\"greek\">μ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">δόξα</span> <span class=\"greek\">κυρίου</span> … <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτόν</span> AcPl Ha 7, 7.—GPt 11:45 (ver <span class=\"greek\">ἀγωνιάω</span>). É incerto, do ponto de vista textual, se o verbo com <span class=\"greek\">μ</span>. em 1 Cl 1:1 é <span class=\"greek\">βλασφημηθῆναι</span> ou <span class=\"greek\">βλαφθῆναι</span>. Em contexto fragmentário AcPl BMM verso 23.—DELG s.v. <span class=\"greek\">μέγας</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγαλωσύνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγαλωσύνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (ver o verbete precedente e o seguinte; Herodian, Gramm. I 335, 18; LXX; En 98:2; 101:3; o texto de Gizé [5:4] apresenta <span class=\"greek\">μεγαλοσύνη</span>; EpArist 192; TestLevi 3:9; 18:8; Ar. 15, 2; Suda; Etym. Mag. p. 275, 44; Byz. Chron. em Psaltes p. 267), condição de grandeza ou preeminência: majestade, usada somente acerca de Deus; em doxologia com <span class=\"greek\">δόξα</span> (e outras ideias semelhantes; En 14:16) Jd 25; 1 Cl 20:12; 61:3; 64; 65:2; MPol 20:2; 21:1 (aqui, como em Ar. 15, 2, referida a Cristo). <span class=\"greek\">τὸ</span> <span class=\"greek\">σκῆπτρον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, o cetro da majestade de Deus 1 Cl 16:2; <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>., pela palavra majestosa de Deus 27:4. <span class=\"greek\">ἀπαύγασμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>., reflexo da majestade de Deus 36:2 (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:3</a>). <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὄνομα</span> <span class=\"greek\">αὐτοῦ</span>, seu nome glorioso, o de Deus 58:1.—Como perífrase para o próprio Deus: <span class=\"greek\">ἐν</span> <span class=\"greek\">δεξιᾷ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>., à direita da Majestade de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:3</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θρόνος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>. 8:1.—DELG s.v. <span class=\"greek\">μέγας</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέγας, μεγάλη, μέγα</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέγας</span>, <span class=\"greek\">μεγάλη</span>, <span class=\"greek\">μέγα</span> (Hom. e posteriores), comparativo <span class=\"greek\">μείζων</span> e, ao lado dele, porque se perdeu gradualmente a percepção de seu sentido comparativo, <span class=\"greek\">μειζότερος</span> 3J 4 (APF 3, 1906, 173; POxy 131, 25; BGU 368, 9; ApcSed 1:5 [cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:13</a>]; ver B-D-F §61, 2; W-S. §11, 4; Mlt-H. 166; Gignac II 158). Superlativo <span class=\"greek\">μέγιστος</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:4</a>).</p><p class=\"entry-text\">① Relativo ao que excede um padrão de comparação com objetos correlatos: grande, volumoso.</p><p class=\"entry-text\">ⓐ Sobre qualquer extensão espacial em todas as direções: <span class=\"greek\">λίθος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:60</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:4</a>. <span class=\"greek\">δένδρον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:19</a>, variante textual (TestAbr B 3 p. 107, 6 [Stone p. 62]). <span class=\"greek\">κλάδοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:32</a>. Edificações 13:2. Peixes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:11</a>. Uma montanha (Tyrtaeus [século VII a.C.], Fgm. 4, 8 D.2; Ps.-Aristot., Mirabilia 138; Theopomp. [século IV a.C.]: 115 Fgm. 78 Jac.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:8</a>. Uma estrela v. 10. Uma fornalha 9:2 (ParJer 6:23). Um dragão (Esth 1:1e; Bel 23 Theod.) 12:3, 9. <span class=\"greek\">ἀετός</span> (Ezk 17:3; ParJer 7:18 [RHarris; omitido por Kraft-Purintun]) v. 14. <span class=\"greek\">μάχαιρα</span>, uma espada comprida 6:4. <span class=\"greek\">ἅλυσις</span>, uma corrente longa 20:1. <span class=\"greek\">πέλαγος</span> AcPl Ha 7, 23 (primeira mão).</p><p class=\"entry-text\">ⓑ Com ideia de amplitude: <span class=\"greek\">ἀνάγαιον</span>, sala espaçosa no andar superior <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:12</a>. <span class=\"greek\">θύρα</span>, porta larga <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:9</a>. Um lagar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:19</a> (<span class=\"greek\">ληνός</span> <span class=\"greek\">μ</span>., “tanque”, JosAs 2:20); <span class=\"greek\">χάσμα</span>, grande abismo (2 Km 18:17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:26</a>. <span class=\"greek\">οἰκία</span> (Jer 52:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:20</a>.</p><p class=\"entry-text\">ⓒ Com palavras que incluem a ideia de número: <span class=\"greek\">ἀγέλη</span> <span class=\"greek\">μ</span>., grande manada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:11</a>. <span class=\"greek\">δεῖπνον</span>, grande banquete, com muitos convidados (Da 5:1 Theod.; JosAs 3:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:16</a>. Também <span class=\"greek\">δοχὴ</span> <span class=\"greek\">μ</span>. (Gen 21:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:29</a>; GJs 6:2.</p><p class=\"entry-text\">ⓓ Sobre idade (Jos., Ant. 12, 207 <span class=\"greek\">μικρὸς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">μέγας</span>=“jovem ou velho”); para incluir todos os envolvidos: <span class=\"greek\">μικροὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεγάλοι</span>, pequenos e grandes (PGM 15, 18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:18</a>; 13:16; 19:5, 18; 20:12. <span class=\"greek\">μικρῷ</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεγάλῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:22</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μικροῦ</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">μεγάλου</span> (Gen 19:11; 4 Km 23:2; 2 Ch 34:30; POxy 1350) 8:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:11</a> (Jer 38:34). <span class=\"greek\">μέγας</span> <span class=\"greek\">γενόμενος</span>, ao atingir a idade adulta 11:24 (Ex 2:11). <span class=\"greek\">ὁ</span> <span class=\"greek\">μείζων</span>, o mais velho (O. Wilck II, 144, 3 [128 d.C.]; 213, 3; 1199, 2; LXX; cf. Polyb. 18, 18, 9 <span class=\"greek\">Σκιπίων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span>; 32, 12, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:12</a>; 13:2 (ambos Gen 25:23).</p><p class=\"entry-text\">② Relativo ao que está acima da média em quantidade: grande; <span class=\"greek\">πορισμός</span>, grande fonte de lucro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:6</a>. <span class=\"greek\">μισθαποδοσία</span>, recompensa abundante <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:35</a>.</p><p class=\"entry-text\">③ Relativo ao que ultrapassa um padrão de intensidade: grande; <span class=\"greek\">δύναμις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:33</a>; 19:8 D. Especialmente do som: alto, forte; <span class=\"greek\">φωνή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:10</a>; <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span> (LXX; TestAbr A 5 p. 82, 20s. [Stone p. 12]; ParJer 2:2; ApcMos 5:21) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:46</a>, 50; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:26</a>; 5:7; 15:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:33</a>; 8:28; 19:37; 23:23 (<span class=\"greek\">Φωναῖς</span> <span class=\"greek\">μεγάλαις</span>), 46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.43\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.57\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:57</a>, 60; 8:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:12</a>; 6:10 e outros; <span class=\"greek\">μεγ</span>. <span class=\"greek\">φωνῇ</span> (ParJer 5:32); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:10</a>; 16:28; <span class=\"greek\">μεγ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">φωνῇ</span> (ParJer 9:8; Jos., Bell. 6, 188) 14:10, variante textual; 26:24; <span class=\"greek\">ἐν</span> <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:2</a>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">σάλπιγγος</span> <span class=\"greek\">μεγάλης</span>, com o som forte de uma trombeta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:31</a>. <span class=\"greek\">κραυγή</span> (Ex 11:6; 12:30) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:9</a>; cf. <span class=\"greek\">μεῖζον</span> <span class=\"greek\">κράζειν</span>, gritar ainda mais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:31</a>. <span class=\"greek\">κοπετός</span> (Gen 50:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:2</a>.—De fenômenos naturais: <span class=\"greek\">ἄνεμος</span> <span class=\"greek\">μ</span>., vento forte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:13</a>. <span class=\"greek\">λαῖλαψ</span> <span class=\"greek\">μ</span>. (Jer 32:32) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:37</a>. <span class=\"greek\">βροντή</span> (Sir 40:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:2</a>. <span class=\"greek\">χάλαζα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:19</a>; 16:21a. <span class=\"greek\">χάλαζα</span> <span class=\"greek\">λίαν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">σφόδρα</span> AcPl Ha 5, 7. <span class=\"greek\">σεισμὸς</span> <span class=\"greek\">μ</span>. (Jer 10:22; Ezk 3:12; 38:19; Jos., Ant. 9, 225) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:24</a>; 28:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:11a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:26</a>. <span class=\"greek\">γαλήνη</span> <span class=\"greek\">μ</span>., grande calmaria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:39</a>; <span class=\"greek\">φῶς</span> <span class=\"greek\">μ</span>., luz intensa (JosAs 6:3; ParJer 9:18 [16]; Plut., Mor. 567f: uma voz divina emana dessa luz; Petosiris, Fgm. 7, linha 39 <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱερὸν</span> <span class=\"greek\">ἄστρον</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">ποιοῦν</span> <span class=\"greek\">φῶς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:16a</a>; GJs 19:2 (Is 9:1). <span class=\"greek\">καῦμα</span> <span class=\"greek\">μ</span>., calor intenso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:9</a> (JosAs 3:3).—De acontecimentos ou fenômenos surpreendentes ou desagradáveis dos mais diversos tipos (<span class=\"greek\">ἀπώλεια</span> Dt 7:23; <span class=\"greek\">θάνατος</span> Ex 9:3; Jer 21:6; <span class=\"greek\">κακόν</span> Philo, Agr. 47): <span class=\"greek\">σημεῖα</span> (Dt 6:22; 29:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:11b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:8</a>. <span class=\"greek\">δυνάμεις</span> 8:13. <span class=\"greek\">ἔργα</span> <span class=\"greek\">μ</span>., feitos poderosos (cf. Judg 2:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:3</a>. <span class=\"greek\">μείζω</span> <span class=\"greek\">τούτων</span>, coisas maiores do que estas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.50\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:50</a> (<span class=\"greek\">μείζονα</span>, variante textual); cf. 5:20; 14:12. <span class=\"greek\">διωγμὸς</span> <span class=\"greek\">μ</span>., perseguição intensa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:1</a>; <span class=\"greek\">θλῖψις</span> <span class=\"greek\">μ</span>., (tempo de) grande sofrimento (1 Macc 9:27) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:22</a>; 7:14. <span class=\"greek\">πειρασμός</span> AcPl Ha 8, 22. <span class=\"greek\">πληγή</span> (Judg 15:8; 1 Km 4:10, 17 e outros; TestReub 1:7; TestSim 8:4; Philo, Sacr. Abel. 134) 16:21b. <span class=\"greek\">θόρυβος</span> GJs 21:1; AcPl Ha 1, 28s. (restaurado, ver AcPlTh [Aa I 258, 6]); <span class=\"greek\">λιμὸς</span> <span class=\"greek\">μ</span>. (4 Km 6:25; 1 Macc 9:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:28</a>; <span class=\"greek\">ἀνάγκη</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:23</a>; <span class=\"greek\">πυρετὸς</span> <span class=\"greek\">μ</span>., febre alta (ver <span class=\"greek\">πυρετός</span>) 4:38.—De emoções: <span class=\"greek\">χαρά</span>, grande alegria (Jon 4:6; JosAs 3:4; 4:2 e outros; Jos., Ant. 12, 91) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:10</a>; 28:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:10</a>; 24:52. <span class=\"greek\">φόβος</span>, grande temor (X., Cyr. 4, 2, 10; Menand., Fgm. 388 Kö.; Jon 1:10, 16; 1 Macc 10:8; TestAbr B 13 p. 117, 18 [Stone p. 82]; JosAs 6:1; GrBar 7:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:9</a>; 8:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:5</a>, 11; AcPl Ha 3, 33. <span class=\"greek\">θυμὸς</span> <span class=\"greek\">μ</span>., grande ira (1 Macc 7:35) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:12</a>. <span class=\"greek\">μείζων</span> <span class=\"greek\">ἀγάπη</span>, amor maior <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:13</a>. <span class=\"greek\">λύπη</span>, profunda tristeza (Jon 4:1; 1 Macc 6:4, 9, 13; TestJob 7:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:2</a>. <span class=\"greek\">σκυθρωπία</span> AcPl Ha 7, 36. <span class=\"greek\">πίστις</span>, fé firme <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:28</a>. <span class=\"greek\">ἔκστασις</span> (cf. Gen 27:33; ParJer 5:8, 12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:42</a>.</p><p class=\"entry-text\">④ Relativo ao que é comparativamente superior em importância: grande.</p><p class=\"entry-text\">ⓐ Acerca de seres racionais: de Deus e outras divindades <span class=\"greek\">θεός</span> (SIG 985, 34 <span class=\"greek\">θεοὶ</span> <span class=\"greek\">μεγάλοι</span> [LBlock, Megaloi Theoi: Roscher II 2523–28, 2536–40; SCole, Theoi Megaloi, The Cult of the Great Gods at Samothrace ’84]; 1237, 5 <span class=\"greek\">ὀργὴ</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μεγάλου</span> <span class=\"greek\">Διός</span>; OGI 50, 7; 168, 6; 716, 1; PStras 81, 14 [115 a.C.] <span class=\"greek\">Ἴσιδος</span> <span class=\"greek\">μεγάλης</span> <span class=\"greek\">μητρὸς</span> <span class=\"greek\">θεῶν</span>; POxy 886, 1; PTebt 409, 11; 22 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">Σάραπις</span>, e outros; PGM 4, 155; 482; 778 e frequentemente; 3052 <span class=\"greek\">μέγ</span>. <span class=\"greek\">θεὸς</span> <span class=\"greek\">Σαβαώθ</span>; 5, 474; Dt 10:17 e outros na LXX; En 103:4; 104:1; Philo, Cher. 29 e outros; Jos., Ant. 8, 319; SibOr 3, 19; 71 e outros.—Thieme 36s.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:13</a> (refere-se a Cristo). <span class=\"greek\">Ἄρτεμις</span> (ver esse verbete) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:27</a>s., 34s. (cf. Ael. Aristid. 48, 21 K.=24 p. 471 D., a exclamação <span class=\"greek\">μέγας</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀσκληπιός</span>); ver New Docs 1, 106, sobre esse epíteto aplicado a divindades. Simão, o mago, é chamado <span class=\"greek\">ἡ</span> <span class=\"greek\">δύναμις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">καλουμένη</span> <span class=\"greek\">μεγάλη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:10b</a> (ver <span class=\"greek\">δύναμις</span> 5). O anjo Miguel Hs 8, 3, 3; cf. 8, 4, 1.—Acerca de pessoas em relação com a Divindade ou que ocupam posição elevada por outros motivos: <span class=\"greek\">ἀρχιερεύς</span> (ver <span class=\"greek\">ἀρχιερεύς</span> 2a e <span class=\"greek\">ἱερεύς</span> a<span class=\"greek\">β</span>.—<span class=\"greek\">ἀρχ</span>. <span class=\"greek\">μέγ</span>. também é a designação do príncipe-sacerdote de Olba [ver PECS 641s.] na Cilícia: MAMA III ’31 p. 67, inscrições 63; 64 [século I a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:14</a>. <span class=\"greek\">προφήτης</span> (Sir 48:22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:16</a>. <span class=\"greek\">ποιμήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:20</a>. Dos governantes em geral: <span class=\"greek\">οἱ</span> <span class=\"greek\">μεγάλοι</span>, os grandes, os que ocupam posições elevadas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:42</a>. De pessoas proeminentes por qualquer motivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:19</a>; 20:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:15</a>, 32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:36</a> D; 8:9 (MSmith, HWolfson Festschr., ’65, 741: <span class=\"greek\">μ</span>. aqui e em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:32</a> pode implicar uma pretensão messiânica).—<span class=\"greek\">μέγας</span> com valor superlativo (2 Km 7:9.—O positivo também é empregado em lugar do superlativo, por exemplo, Sallust. 4 p. 6, 14, onde Páris chama Afrodite de <span class=\"greek\">καλή</span>=“a mais bela”; Diod S 17, 70, 1 <span class=\"greek\">πολεμία</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πόλεων</span>=“a mais hostil” [ou “especialmente hostil”] entre as cidades) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:48</a> (oposto a <span class=\"greek\">ὁ</span> <span class=\"greek\">μικρότερος</span>).—Comparativo <span class=\"greek\">μείζων</span>, maior, de Deus (Ael. Aristid. 27, 3 K.=16 p. 382 D.; PGM 13, 689 <span class=\"greek\">ἐπικαλοῦμαί</span> <span class=\"greek\">σε</span>, <span class=\"greek\">τὸν</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">μείζονα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:13</a>; 1J 3:20; 4:4. Mais proeminente ou notável em razão de certas vantagens <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:28</a>; 22:26s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:12</a>; 8:53; 13:16ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:5</a>. Definido mais precisamente: <span class=\"greek\">ἰσχύϊ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δυνάμει</span> <span class=\"greek\">μείζων</span>, maior em força e poder <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:11</a>. <span class=\"greek\">μεῖζον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span>, algo maior que o templo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:6</a>. <span class=\"greek\">μείζων</span> com sentido superlativo (Ps.-Apollod., Epit. 7, 8 Wagner: <span class=\"greek\">Ὀδυσσεὺς</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">κριοὺς</span> <span class=\"greek\">ὁμοῦ</span> <span class=\"greek\">συνδέων</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μείζονι</span> <span class=\"greek\">ὑποδύς</span>; Appian, Bell. Civ. 2, 87 §366 <span class=\"greek\">ἐν</span> <span class=\"greek\">παρασκευῇ</span> <span class=\"greek\">μείζονι</span>=“com a maior preparação”; Vett. Val. 62, 24; TestJob 3:1 <span class=\"greek\">ἐν</span> <span class=\"greek\">μείζονι</span> <span class=\"greek\">φωτί</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:1</a>, 4; 23:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:46</a>; 22:24, 26.</p><p class=\"entry-text\">ⓑ Acerca de coisas: grande, sublime, importante; <span class=\"greek\">μυστήριον</span> (GrBar 1:6; 2:6; ApcMos 34; Philo, Leg. All. 3, 100 e outros; Just., A I, 27, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:16</a>. Do sábado que inaugura um período festivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:31</a>; MPol 8:1b. Especialmente do dia do juízo divino (LXX; En 22:4; ApcEsdr 3:3 p. 27, 7 Tdf.; Just., D. 49, 2 e outros; cf. TestAbr A 13 p. 92, 11 [Stone p. 32]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:20</a> (Jo 3:4); Jd 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:17</a>; 16:14. Da extraordinária capacidade didática de Paulo <span class=\"greek\">μ</span>̣<span class=\"greek\">ε</span>̣<span class=\"greek\">γάλῃ</span> <span class=\"greek\">καθ</span>̣[<span class=\"greek\">ηγήσει</span>] AcPl Ha 6, 30s.—<span class=\"greek\">μέγας</span> em sentido superlativo (Plut., Mor. 35a com <span class=\"greek\">πρῶτος</span>; Himerius, Or. 14 [Ecl. 15], 3 <span class=\"greek\">μέγας</span>=“o maior”, “verdadeiramente grande”; B-D-F §245, 2; ver Rob. 669) <span class=\"greek\">ἐντολή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:36</a>, 38. <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἑορτῆς</span>, o grande dia da festa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:37</a> (cf. Lucian, Pseudolog. 8 <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">νουμηνία</span> [no começo do ano]); Mel., P. 79, 579; 92, 694 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐορτῇ</span>; GJs 1:2; 2:2 (ver deStrycker sobre 1:2). Do dia do parto de Maria <span class=\"greek\">ὡς</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σήμερον</span> <span class=\"greek\">ἡμέρα</span>, que grande dia é este GJs 19:2. <span class=\"greek\">μείζων</span>, como comparativo (Chion, Ep. 16, 8, a filosofia como <span class=\"greek\">νόμος</span> <span class=\"greek\">μείζων</span>=“lei superior”; Sir 10:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:36</a>; 1J 5:9. <span class=\"greek\">μ</span>. <span class=\"greek\">ἁμαρτία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:11</a> (cf. escólio a Pla. 189d <span class=\"greek\">ἁμαρτήματα</span> <span class=\"greek\">μεγάλα</span>; Ex 32:30s.). <span class=\"greek\">τὰ</span> <span class=\"greek\">χαρίσματα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μείζονα</span>, os dons espirituais mais importantes (no sentido atribuído por Paulo à palavra) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:31</a>. Como superlativo (Epict. 3, 24, 93; Stephan. Byz. s.v. <span class=\"greek\">Ὕβλαι</span>: a maior de três cidades é <span class=\"greek\">ἡ</span> <span class=\"greek\">μείζων</span> [seguida de <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐλάττων</span> e, por fim, <span class=\"greek\">ἡ</span> <span class=\"greek\">μικρά</span>=“a menor”]. O comparativo também exerce a função de superlativo, por exemplo, em Diod S 20, 22, 2, onde <span class=\"greek\">πρεσβύτερος</span> é o mais velho de 3 homens) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:13</a> (por meio do superlativo <span class=\"greek\">μ</span>., Paulo destaca, dentre a tríade, a qualidade que mais lhe interessa neste contexto, tal como Ael. Aristid. 45, 16 K., por meio de <span class=\"greek\">αὐτός</span> ao fim de <span class=\"greek\">θεοί</span>, destaca Serápis, a única divindade que o afeta).—O superlativo <span class=\"greek\">μέγιστος</span>, empregado ocasionalmente por autores contemporâneos, ocorre apenas uma vez no NT, onde é usado em sentido elativo: muito grande, extraordinário (Diod S 2, 32, 1) <span class=\"greek\">ἐπαγγέλματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:4</a>.—Quanto ao emprego adverbial em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:29</a>, ver <span class=\"greek\">ὀλίγος</span> 2b<span class=\"greek\">β</span>.—Neutro plural: <span class=\"greek\">μεγάλα</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινι</span>, fazer grandes coisas por alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:49</a> (cf. Dt 10:21). <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">μεγάλα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βλασφημίας</span>, proferir palavras arrogantes e blasfêmias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:5</a> (Da 7:8; cf. En 101:3). <span class=\"greek\">ἐποίει</span> <span class=\"greek\">μεγ</span>̣[<span class=\"greek\">ά</span>]<span class=\"greek\">λα</span> <span class=\"greek\">καὶ</span> [<span class=\"greek\">θα</span>]<span class=\"greek\">υ</span>̣[<span class=\"greek\">μά</span>]<span class=\"greek\">σ</span>̣<span class=\"greek\">ι</span>̣<span class=\"greek\">α</span>̣ (Just., A I, 62, 4), (Cristo) continuava a realizar feitos grandes e maravilhosos AcPl Ha 8, 33//BMM verso 6.</p><p class=\"entry-text\">⑤ Relativo ao que é incomum ou surpreendente, neutro: <span class=\"greek\">μέγα</span> <span class=\"greek\">εἰ</span> … <span class=\"greek\">θερίσομεν</span>;, seria algo extraordinário (isto é, esperamos demais? = coloquialmente “é grande coisa?”) se desejarmos colher? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:11</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">οὖν</span>, <span class=\"greek\">εἰ</span>, não surpreende, portanto, que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:15</a> (sobre essa construção, cf. Pla., Menex. 235d; Plut., Mor. 215f; Gen 45:28; ver AFridrichsen, ConNeot 2, ’36, 46).—B. 878s.; 1309. DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέγεθος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέγεθος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (ver <span class=\"greek\">μέγας</span>; Hom. e posteriores).</p><p class=\"entry-text\">① Qualidade do que excede um padrão de magnitude física: tamanho, dimensão, literalmente (Appian, Bell. Civ. 1, 50 §219 <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">μεγέθει</span> <span class=\"greek\">μέγας</span>; Heraclid. Crit. 23 [p. 82, 14 Pfister]; <span class=\"greek\">μεγάλη</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μεγέθει</span>: Ps.-Dicaearch. p. 145 linha 5 F.; Did., Gen. 35, 10): <span class=\"greek\">ὑψηλὸς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μεγέθει</span>, de estatura realmente muito elevada Hs 9, 6, 1. <span class=\"greek\">τὰ</span> <span class=\"greek\">μεγέθη</span> [<span class=\"greek\">τῶν</span> <span class=\"greek\">θηρίων</span>], o enorme tamanho dos animais AcPl Ha 1, 34.</p><p class=\"entry-text\">② Qualidade do que supera um padrão de excelência: grandeza; <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χαρᾶς</span> <span class=\"greek\">μ</span>.=a grande alegria AcPl Ha 6, 9s. De Deus (inscrição em CB I/2, 700 n.º 635, 4 <span class=\"greek\">τὸ</span> <span class=\"greek\">μέγεθος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>; Philo, Spec. Leg. 1, 293 <span class=\"greek\">τὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μ</span>.; Ath. 22, 7 <span class=\"greek\">τοῦ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>. Hipóstases divinas Hippol., Ref. 5, 8, 3; 10, 10, 2): <span class=\"greek\">τί</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπερβάλλον</span> <span class=\"greek\">μέγεθος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δυνάμεως</span> <span class=\"greek\">αὐτοῦ</span>, quão extraordinariamente grande é o poder (de Deus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:19</a> (cf. Philo, Op. M. 23, final, <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. [<span class=\"greek\">τῶν</span> <span class=\"greek\">δυνάμεων</span> <span class=\"greek\">θεοῦ</span>]; ver também New Docs 4, 107). <span class=\"greek\">ἐν</span> <span class=\"greek\">μεγέθει</span> IEph ins, certamente, não se liga gramaticalmente a <span class=\"greek\">θεοῦ</span>, que, antes, se relaciona com o <span class=\"greek\">πληρώματι</span> seguinte; não obstante, descreve a natureza de Deus. <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">μαρτυρίας</span>, a grandeza de seu martírio MPol 17:1 (cf. <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώσεως</span> Iren. 1, 13, 6 [Harv. I, 123, 3]; Did., Gen. 115, 2). <span class=\"greek\">ἀπολαμβάνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">μ</span>., recuperar sua grandeza própria, acerca de uma comunidade ISm 11:2. <span class=\"greek\">μεγέθους</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστιανισμός</span>, o cristianismo é (verdadeiramente) grande IRo 3:3.—DELG s.v. <span class=\"greek\">μέγας</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεγιστάν, ᾶνος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεγιστάν</span>, <span class=\"greek\">ᾶνος</span>, <span class=\"greek\">ὁ</span> (de <span class=\"greek\">μέγας</span>, por intermédio de <span class=\"greek\">μέγιστος</span>); quase exclusivamente — e sempre em nossa literatura — no plural <span class=\"greek\">μεγιστᾶνες</span>, <span class=\"greek\">ων</span> (LXX; PsSol 2:32; TestSol 10:28 C [acusativo -<span class=\"greek\">ους</span>]; JosAs; Manetho, Apot. 4, 41; Artem. 1, 2 p. 8, 16; 3, 9; Jos., Ant. 11, 37; 20, 26, Vi. 112; 149; Just., D. 107, 2; Tat. 3, 4;; PGM 13, 251 [singular]; Phryn. 196s. Lob.—B-D-F §2: dorismo), pessoa de posição elevada, grande personagem, cortesão, magnata na corte de Herodes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:21</a>. Em geral, <span class=\"greek\">οἱ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:23</a>; (com <span class=\"greek\">βασιλεῖς</span>) 6:15. C-HHunzinger, ZNW Beih. 26, ’60, 209–20: Evangelho de Tomé.—DELG s.v. <span class=\"greek\">μέγας</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέγιστος</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέγιστος</span>: ver <span class=\"greek\">μέγας</span> 4.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθερμηνεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεθερμηνεύω</span> (ver <span class=\"greek\">ἑρμηνεύω</span>), infinitivo aoristo <span class=\"greek\">μεθερμηνεῦσαι</span> Sir prólogo linha 30 (Polyb. 6, 26, 6; Diod S 1, 11, 2; Plut., Cato Maj. 2, 6; Herm. Wr. 12, 13a; PTebt 164 I, 1 [século II a.C.]; BGU 1002 II, 1 e outros; Sir prólogo, ver acima; EpArist 38; Jos., Ant. 8, 142, C. Ap. 1, 54), traduzir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:8</a> (aqui “Elimas” ou explica Bar-Jesus, ou traduz <span class=\"greek\">μάγος</span>; ver <span class=\"greek\">Ἐλύμας</span>). Principalmente na fórmula <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">μεθερμηνευόμενον</span>, que significa (quando traduzido) (Theophilus: 296 Fgm. 3 Jac.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:41</a>; 15:22, 34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:36</a>. Também <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">λέγεται</span> <span class=\"greek\">μ</span>. (variante textual <span class=\"greek\">ἑρμηνευόμενον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:38</a>.—DELG s.v. <span class=\"greek\">ἑρμηνεύς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέθη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέθη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (ver <span class=\"greek\">μεθύω</span>; Antiphon e posteriores; Epict. 3, 26, 5; Herm. Wr. 1, 27; papiros, LXX; PsSol 8:14; OdeSol 11:8; TestSol 18:16 P; Test12Patr; GrBar; Philo; Jos., Ant. 1, 301; 11, 42; Ar. 10, 8; Just., A II, 2, 7), embriaguez; <span class=\"greek\">ἐν</span> <span class=\"greek\">κραιπάλῃ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μ</span>., com dissipação e embriaguez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:34</a>. Também no plural com o mesmo sentido (Pla. e outros; também Vett. Val. 90, 13; PGiss 3, 8; Jdth 13:15; GrBar) 1 Cl 30:1; AcPl Ha 1, 12; com <span class=\"greek\">κῶμοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:13</a>. Numa lista de vícios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:21</a> (entretanto, parece que, nas duas últimas passagens, a proximidade de <span class=\"greek\">κῶμοι</span>=“festanças desenfreadas” pode influenciar <span class=\"greek\">μέθαι</span> no sentido de “bebedeira”; a esse respeito, cf. Diod S 16, 19, 2, onde todos os manuscritos concordam na leitura <span class=\"greek\">οἱ</span> <span class=\"greek\">στρατηγοὶ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μέθης</span> <span class=\"greek\">μεθύοντες</span> = “os generais que estavam embriagados pelas festanças”).—DELG s.v. <span class=\"greek\">μέθυ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθιστάνω</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεθιστάνω</span>: ver verbete seguinte.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθίστημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεθίστημι</span> (ver <span class=\"greek\">ἵστημι</span>), forma alternativa <span class=\"greek\">μεθιστάνω</span> (Hv 1, 3, 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:2</a>, variante textual), futuro <span class=\"greek\">μεταστήσω</span> LXX; 1º aoristo <span class=\"greek\">μετέστησα</span>; 2º aoristo <span class=\"greek\">μετέστην</span> LXX. Passivo: aoristo <span class=\"greek\">μετεστάθην</span>; subjuntivo <span class=\"greek\">μετασταθῶ</span> (Hom. e posteriores; inscrições, papiros, LXX, TestSol; TestAbr A 20 p. 103, 8 [Stone p. 54]; TestIss 1:13; Joseph.).</p><p class=\"entry-text\">① Transferir de um lugar para outro: remover.</p><p class=\"entry-text\">ⓐ Acerca de coisas, <span class=\"greek\">τὶ</span>, alguma coisa: <span class=\"greek\">ὄρη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:2</a> (Is 54:10). Céus, montanhas, colinas e mares Hv 1, 3, 4. (<span class=\"greek\">ἡμᾶς</span>) <span class=\"greek\">μετέστησεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span>, (Deus) nos transferiu para o reino <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:13</a> (cf. Jos., Ant. 9, 235 <span class=\"greek\">μ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αὑτοῦ</span> <span class=\"greek\">βασιλείαν</span>.—<span class=\"greek\">μ</span>. <span class=\"greek\">εἰς</span>=“transplantar para” também Alex. Aphr., Mixt. II 2 p. 219, 28; 230, 29; cf. <span class=\"greek\">τὸ</span> <span class=\"greek\">μεταστῆναι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὁρατῶν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀόρατα</span> como descrição de <span class=\"greek\">ἔκστασις</span> Did., Gen. 230, 9).</p><p class=\"entry-text\">ⓑ Acerca de pessoas: remover, destituir (3 Km 15:13; 1 Macc 11:63; Jos., Ant. 19, 297; 20, 16); <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τόπου</span>, tirar alguém de seu lugar 1 Cl 44:5. Passivo: ser afastado; <span class=\"greek\">ὅταν</span> <span class=\"greek\">μετασταθῶ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκονομίας</span>, quando eu for dispensado de meu cargo de administrador <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:4</a> (Vi. Aesopi G 9 <span class=\"greek\">μεταστήσω</span> <span class=\"greek\">σε</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκονομίας</span>=“eu te destituirei do cargo de administrador”.—<span class=\"greek\">μ</span>. <span class=\"greek\">ἐκ</span> como em Jos., Vi. 195).—Provavelmente este também é o sentido em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:22</a> <span class=\"greek\">μεταστήσας</span> <span class=\"greek\">αὐτόν</span>, depois de o ter destituído (do trono; cf. Da 2:21). A expressão em sua forma plena, <span class=\"greek\">μ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ζῆν</span>, “matar alguém” (Diod S 2, 57, 5; 4, 55, 1; cf. 3 Macc 6:12), dificilmente parece aplicável aqui.</p><p class=\"entry-text\">② Levar alguém a outro ponto de vista: afastar, desencaminhar, também em sentido desfavorável; extensão figurada de 1 (X., Hell. 2, 2, 5; Plut., Galba 1059 [14, 3] <span class=\"greek\">τοὺς</span> <span class=\"greek\">πλείους</span> <span class=\"greek\">μετέστησαν</span>; Josh 14:8) <span class=\"greek\">ἱκανὸν</span> <span class=\"greek\">ὄχλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:26</a>.—DELG s.v. <span class=\"greek\">ἵστημι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθοδεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεθοδεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>, também -<span class=\"greek\">δία</span> (POxy 136, 18; 24; 1134, 9 e outros, embora somente nos papiros tardios [421 d.C. e posteriores] e no sentido de “método” etc.; Hesychius; Suda); em nossa literatura (somente em Efésios), exclusivamente com sentido desfavorável (ver <span class=\"greek\">μεθοδεύω</span>): maquinação, astúcia; <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πλάνης</span>, em maquinações enganosas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:14</a>. Plural: artimanhas, estratagemas (Suda: <span class=\"greek\">μεθοδείας</span>· <span class=\"greek\">τέχνας</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">δόλους</span>; Iren. 1, 9, 1 [Harv. I 82, 1]: <span class=\"greek\">ἵνα</span> … <span class=\"greek\">κατανοήσῃς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πανουργίαν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πονηρίαν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πλάνης</span>); <span class=\"greek\">αἱ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span> (Cyrill. of Scyth. p. 30, 21 <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">δαιμόνων</span>) 6:11, 12 P46.—DELG s.v. <span class=\"greek\">ὁδός</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0228-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθοδεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεθοδεύω</span> (ver verbete precedente), aoristo, 3ª pessoa do singular <span class=\"greek\">μεθώδευσεί</span> 2 Km 19:28 (encontrado não raramente em autores posteriores, incluindo PGM 13, 713; LXX, Philo), em sentido desfavorável: fraudar, enganar, perverter (Chariton 7, 6, 10 <span class=\"greek\">μεθοδεύεται</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">ἐπαγγελίαις</span>=“uma mulher é enganada por promessas”; POxy 2342, 27 [102 d.C.]; Philo, Mos. 2, 212 <span class=\"greek\">ὅπερ</span> <span class=\"greek\">μεθοδεύουσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">λογοθῆραι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σοφισταί</span>; 2 Km 19:28); <span class=\"greek\">τὰ</span> <span class=\"greek\">λόγια</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἰδίας</span> <span class=\"greek\">ἐπιθυμίας</span>, perverter as palavras do Senhor para satisfazer os próprios desejos Pol 7:1.—DELG s.v. <span class=\"greek\">ὁδός</span>. M-M. TW.</p></section></article>"};
